/**
 * File-name → bundled asset. Keys are the asset file name with dots and
 * dashes replaced by underscores, so the lookup is case-insensitive-ish
 * and safe as an object key.
 */
export { PRODUCT_IMAGE_ASSETS };

/**
 * Resolve an image URL to a renderable source.
 *
 * - bundled asset when the file name is known (offline, instant)
 * - the remote URI otherwise (the backend CDN case)
 * - `undefined` when there is nothing to show
 */
export function resolveImage(url?: string | null): ImageSourcePropType | undefined {
  if (!url) return undefined;

  const file = url.split('/').pop()?.split('?')[0];
  if (!file) return { uri: url };

  const key = file.replace(/[.-]/g, '_');
  const bundled = PRODUCT_IMAGE_ASSETS[key];
  if (bundled) return bundled;

  return { uri: url };
}
